var a=91;var o=`091-reduction-and-liquid-concentration`;var i=`070`;var n={en:`Reduction and Liquid Concentration`,ua:`Уварювання та концентрування рідин`};var s={short:`Reduction concentrates a sauce, stock, or other liquid by allowing water to evaporate during heating. It intensifies flavors and may change viscosity, but also concentrates salt, acidity, sweetness, and potential bitterness.`,sections:[{title:`Core idea`,text:`A wider pan exposes more liquid surface, commonly allowing quicker evaporation than a narrow pot at comparable heating. As water leaves, dissolved sugars, salts, gelatin, and aromatic compounds become more concentrated; some aromas also evaporate or change with heat. Reduction does not necessarily produce a thick sauce if the liquid lacks thickening components.`},{title:`Scientific / practical principles`,text:`Evaporation requires energy, so burner output, pan shape, airflow, and liquid composition affect speed. A simmer offers more control than violent boiling, especially for milk, sweet sauces, or delicate stocks. Where a stock contains gelatin, cooling will make the concentrated liquid seem thicker than it is when hot.`},{title:`How to apply it`,text:`Choose an appropriately sized pan, cook uncovered at a controlled simmer, and occasionally stir or skim. Mark the starting level or measure the liquid so you can aim for half-volume or another endpoint. Taste as it concentrates and add salt late. If reducing wine or a strongly acidic sauce, aim for balanced flavor rather than a predetermined minute count.`},{title:`Practical example`,text:`After cooking mushrooms, deglaze the skillet with unsalted stock and reduce from 200 mL to roughly 100 mL, then finish with a small amount of butter. The resulting sauce tastes fuller and coats food more readily. Use the volume goal as a guide, not an exact prediction of thickness.`},{title:`Common mistakes and limitations`,text:`Do not reduce salty broth aggressively without tasting: the same salt remains in less water. Alcohol is not guaranteed to disappear fully during reduction, and an overly acidic or bitter liquid becomes unpleasantly strong. Thick sweet reductions can scorch and require closer attention.`},{title:`Related theories`,text:`091, 047, 067, 176.`}]};var r={short:`Уварювання є концентруванням бульйону, соусу або іншої рідини шляхом випаровування частини води. Смак стає насиченішим, іноді зростає густота, але одночасно посилюються солоність, кислотність, солодкість і гіркота.`,sections:[{title:`Суть`,text:`У широкому посуді за подібного нагрівання рідина зазвичай випаровується швидше, ніж у вузькій високій каструлі. Коли вода зникає, концентрація солей, цукрів, желатину та інших речовин зростає; частина летких ароматів теж втрачається або змінюється. Саме уварювання не обов’язково зробить соус густим, якщо в ньому немає компонентів, що створюють в’язкість.`},{title:`Наукові та практичні принципи`,text:`Випаровування потребує енергії, тому швидкість залежить від потужності плити, форми посуду, руху повітря та складу рідини. Слабке кипіння дає більше контролю, особливо для молочних чи солодких соусів. Бульйон із желатином після охолодження здаватиметься густішим, ніж у гарячому стані.`},{title:`Як застосовувати`,text:`Візьміть широкий посуд, залиште його без кришки та підтримуйте рівне помірне кипіння. Позначте початковий рівень або виміряйте об’єм, якщо хочете зменшити його вдвічі. Періодично помішуйте, знімайте піну та пробуйте соус. Сіль додавайте ближче до завершення. Для кислого соусу орієнтуйтеся на баланс, а не лише на години.`},{title:`Практичний приклад`,text:`Після обсмажування грибів додайте на сковороду 200 мл несолоного бульйону й уваріть приблизно до 100 мл, після чого введіть трохи вершкового масла. Соус стане виразнішим і краще вкриватиме гриби. Об’єм є орієнтиром, а не гарантією точної густоти.`},{title:`Поширені помилки й обмеження`,text:`У солоному бульйоні після уварювання лишається майже та сама кількість солі, але менше води. Алкоголь не обов’язково випаровується повністю, а надмірно кислі чи гіркі нотки посилюються. Густі солодкі соуси легко пригорають.`},{title:`Пов’язані теорії`,text:`091, 047, 067, 176.`}]};var l=[91,47,67,176];var c=`References / Джерела`;var d=[`https://rouxbe.com/cooking-courses/culinary-foundations-rouxbe`,`https://www.heart.org/en/healthy-living/healthy-eating/cooking-skills/cooking/techniques/healthy-cooking-methods`];var u={id:91,slug:o,group:`070`,title:n,en:s,ua:r,related:l,referenceTitle:c,references:d};export{u as default,s as en,i as group,a as id,c as referenceTitle,d as references,l as related,o as slug,n as title,r as ua};